13	static void zero_decision(struct vg_ota_boot_decision *out)
14	{
15	  uint8_t *p = (uint8_t *)out;
16	  uint32_t i;
17	
18	  for (i = 0; i < sizeof(*out); i++)
19	    {
20	      p[i] = 0;
21	    }
22	
23	  out->slot = VG_OTA_BCB_SLOT_A;
24	  out->bcb_which = 0xffu;
25	}
