35	static int read_bcb(struct vg_ota_fat_volume *vol, uint32_t dir_cluster,
36	                    const char name[11], uint8_t *buf, int *present,
37	                    uint32_t *error)
38	{
39	  struct vg_ota_fat_entry entry;
40	  int ret;
41	
42	  *present = 0;
43	  ret = vg_ota_fat_find(vol, name, dir_cluster, &entry);
44	  if (ret == -ENOENT)
45	    {
46	      return 0;
47	    }
48	
49	  if (ret != 0)
50	    {
51	      *error = (uint32_t)(-ret);
52	      return ret;
53	    }
54	
55	  *present = 1;
56	
57	  if ((entry.attr & 0x10) != 0 || entry.size != VG_OTA_BCB_FILE_BYTES)
58	    {
59	      clear_bytes(buf, VG_OTA_BCB_FILE_BYTES);
60	      *error = (uint32_t)EINVAL;
61	      return 0;
62	    }
63	
64	  ret = vg_ota_fat_read(vol, &entry, 0, buf, VG_OTA_BCB_FILE_BYTES);
65	  if (ret != 0)
66	    {
67	      clear_bytes(buf, VG_OTA_BCB_FILE_BYTES);
68	      *error = (uint32_t)(-ret);
69	      return 0;
70	    }
71	
72	  return 0;
73	}
