75	int vg_ota_boot_decide(vg_ota_block_read_fn read, void *ctx,
76	                       uint32_t device_sectors,
77	                       struct vg_ota_boot_decision *out)
78	{
79	  struct vg_ota_fat_volume vol;
80	  struct vg_ota_fat_entry dir;
81	  struct vg_ota_bcb bcb;
82	  uint8_t bcb0[VG_OTA_BCB_FILE_BYTES];
83	  uint8_t bcb1[VG_OTA_BCB_FILE_BYTES];
84	  int have0 = 0;
85	  int have1 = 0;
86	  int valid0 = 0;
87	  int valid1 = 0;
88	  uint32_t which = 0xffu;
89	  uint32_t err0 = 0;
90	  uint32_t err1 = 0;
91	  uint32_t i;
92	  int ret;
93	
94	  if (out == 0 || read == 0)
95	    {
96	      return -EINVAL;
97	    }
98	
99	  zero_decision(out);
100	
101	  for (i = 0; i < VG_OTA_BCB_FILE_BYTES; i++)
102	    {
103	      bcb0[i] = 0;
104	      bcb1[i] = 0;
105	    }
106	
107	  ret = vg_ota_fat_mount(&vol, read, ctx, device_sectors);
108	  if (ret != 0)
109	    {
110	      out->slot = VG_OTA_BCB_SLOT_A;
111	      if (ret == -EIO)
112	        {
113	          out->reason = VG_OTA_BOOT_REASON_A_EMMC_ERROR;
114	          out->emmc_error = 1;
115	        }
116	      else
117	        {
118	          out->reason = VG_OTA_BOOT_REASON_A_FAT_ERROR;
119	          out->fat_error = (uint32_t)(-ret);
120	        }
121	
122	      return 0;
123	    }
124	
125	  out->fat_type = (uint32_t)vol.info.type;
126	
127	  ret = vg_ota_fat_find(&vol, g_name_vgota, 0, &dir);
128	  if (ret != 0)
129	    {
130	      out->slot = VG_OTA_BCB_SLOT_A;
131	      if (ret == -ENOENT)
132	        {
133	          out->reason = VG_OTA_BOOT_REASON_A_NO_STAGING;
134	        }
135	      else
136	        {
137	          out->reason = VG_OTA_BOOT_REASON_A_READ_ERROR;
138	          out->bcb_error = (uint32_t)(-ret);
139	        }
140	
141	      return 0;
142	    }
143	
144	  if ((dir.attr & 0x10) == 0 || dir.first_cluster < 2)
145	    {
146	      out->slot = VG_OTA_BCB_SLOT_A;
147	      out->reason = VG_OTA_BOOT_REASON_A_READ_ERROR;
148	      out->bcb_error = (uint32_t)ENOTDIR;
149	      return 0;
150	    }
151	
152	  ret = read_bcb(&vol, dir.first_cluster, g_name_bcb0, bcb0,
153	                 &have0, &err0);
154	  if (ret != 0 && ret != -ENOENT)
155	    {
156	      out->slot = VG_OTA_BCB_SLOT_A;
157	      out->reason = VG_OTA_BOOT_REASON_A_READ_ERROR;
158	      out->bcb_error = (uint32_t)(-ret);
159	      return 0;
160	    }
161	
162	  ret = read_bcb(&vol, dir.first_cluster, g_name_bcb1, bcb1,
163	                 &have1, &err1);
164	  if (ret != 0 && ret != -ENOENT)
165	    {
166	      out->slot = VG_OTA_BCB_SLOT_A;
167	      out->reason = VG_OTA_BOOT_REASON_A_READ_ERROR;
168	      out->bcb_error = (uint32_t)(-ret);
169	      return 0;
170	    }
171	
172	  ret = vg_ota_bcb_select(bcb0, VG_OTA_BCB_FILE_BYTES, have0,
173	                          bcb1, VG_OTA_BCB_FILE_BYTES, have1,
174	                          &bcb, &which, &valid0, &valid1);
175	
176	  out->bcb_valid0 = (uint32_t)valid0;
177	  out->bcb_valid1 = (uint32_t)valid1;
178	
179	  if (ret != 0)
180	    {
181	      out->slot = VG_OTA_BCB_SLOT_A;
182	      out->reason = (have0 || have1) ? VG_OTA_BOOT_REASON_A_BCB_INVALID :
183	                                       VG_OTA_BOOT_REASON_A_NO_BCB;
184	      out->bcb_error = err0 != 0 ? err0 : err1;
185	      if (out->bcb_error == 0 && ret != -ENOENT)
186	        {
187	          out->bcb_error = (uint32_t)(-ret);
188	        }
189	      return 0;
190	    }
191	
192	  out->bcb_which = which;
193	  out->bcb_seq = bcb.seq;
194	  out->bcb_state = bcb.state;
195	  out->bcb_slot = bcb.slot;
196	
197	  if (bcb.state == VG_OTA_BCB_STATE_PENDING)
198	    {
199	      /* Ticket 04 installs the image into slot B here.  Until that path
200	       * exists a pending request must not jump into a partially written
201	       * slot, so the device stays on A.
202	       */
203	      out->reason = VG_OTA_BOOT_REASON_A_PENDING;
204	      return 0;
205	    }
206	
207	  if (bcb.state == VG_OTA_BCB_STATE_FAILED)
208	    {
209	      out->reason = VG_OTA_BOOT_REASON_A_FAILED;
210	      return 0;
211	    }
212	
213	  if (bcb.slot != VG_OTA_BCB_SLOT_B)
214	    {
215	      out->reason = VG_OTA_BOOT_REASON_SLOT_A;
216	      return 0;
217	    }
218	
219	  out->slot = VG_OTA_BCB_SLOT_B;
220	  out->reason = bcb.state == VG_OTA_BCB_STATE_TRIAL ?
221	                VG_OTA_BOOT_REASON_B_TRIAL : VG_OTA_BOOT_REASON_B_CONFIRMED;
222	  return 0;
223	}
