129	static void qspi_wait_idle(void)
130	{
131	  uint32_t timeout = 1000000u;
132	
133	  while ((REG32(QSPI_SR) & QSPI_SR_BUSY) != 0 && timeout-- > 0)
134	    {
135	      __asm__ volatile ("nop");
136	    }
137	}
