193	static void qspi_enter_memory_mapped(void)
194	{
195	  /* Dual-QSPI SPI (1-1-1) memory-mapped mode.
196	   *
197	   * Hardware evidence on this STM32H750B-DK:
198	   * - SPI mmap (CCR=0x0d003513) returns a valid vector table at 0x90000000
199	   * - QPI mmap (CCR=0x0f283fec) returns 0x88888888 and cannot boot XIP
200	   * - OpenOCD stmqspi also cannot JEDEC-probe the dual MT25TL01G
201	   *
202	   * Mirror OpenOCD board/stm32h7x_dual_qspi.cfg qspi_init 0 (SPI path).
203	   */
204	  qspi_gpio_init();
205	
206	  REG32(QSPI_CR) = 0x05500058u;
207	  REG32(QSPI_DCR) = 0x001a0200u;
208	
209	  REG32(QSPI_LPTR) = 0x00001000u;
210	  REG32(QSPI_CCR) = 0x0d002503u;
211	  mmw(QSPI_CR, QSPI_CR_EN, 0);
212	
213	  /* Exit QPI in case a previous image left the chips in QPI mode. */
214	  qspi_abort();
215	  REG32(QSPI_CCR) = 0x000003f5u;
216	  short_delay();
217	
218	  /* Memory-mapped READ with 4-byte addresses (SPI, not QPI). */
219	  qspi_abort();
220	  REG32(QSPI_CCR) = 0x0d003513u;
221	  short_delay();
222	}
