230	static int qspi_wait_tcf(void)
231	{
232	  uint32_t timeout = 20000000u;
233	
234	  while (timeout-- > 0)
235	    {
236	      uint32_t sr = REG32(QSPI_SR);
237	
238	      if ((sr & QSPI_SR_TEF) != 0)
239	        {
240	          return -1;
241	        }
242	
243	      if ((sr & QSPI_SR_TCF) != 0)
244	        {
245	          return 0;
246	        }
247	    }
248	
249	  return -1;
250	}
