263	static int qspi_read_data(uint8_t *buf, uint32_t len)
264	{
265	  volatile uint8_t *dr = (volatile uint8_t *)QSPI_DR;
266	  uint32_t remaining = len;
267	  uint32_t timeout;
268	  uint32_t sr;
269	
270	  while (remaining > 0)

271	    {
272	      timeout = 20000000u;
273	      for (; ; )
274	        {
275	          sr = REG32(QSPI_SR);
276	          if ((sr & QSPI_SR_TEF) != 0)
277	            {
278	              return -1;
279	            }
280	
281	          if (((sr & QSPI_SR_FLEVEL_MASK) >> QSPI_SR_FLEVEL_SHIFT) != 0 ||
282	              (sr & QSPI_SR_TCF) != 0)
283	            {
284	              break;
285	            }
286	
287	          if (timeout-- == 0)
288	            {
289	              return -1;
290	            }
291	        }
292	
293	      while (remaining > 0)
294	        {
295	          sr = REG32(QSPI_SR);
296	          if (((sr & QSPI_SR_FLEVEL_MASK) >> QSPI_SR_FLEVEL_SHIFT) == 0)
297	            {
298	              break;
299	            }
300	
301	          *buf++ = dr[0];
302	          remaining--;
303	        }
304	
305	      if ((REG32(QSPI_SR) & QSPI_SR_TCF) != 0)
306	        {
307	          break;
308	        }
309	    }
310	
311	  if (remaining != 0)
312	    {
313	      return -1;
314	    }
315	
316	  if (qspi_wait_tcf() != 0)
317	    {
318	      return -1;
319	    }
320	
321	  qspi_clear_flags();
322	  return 0;
323	}
