325	static int qspi_write_data(const uint8_t *buf, uint32_t len)
326	{
327	  volatile uint8_t *dr = (volatile uint8_t *)QSPI_DR;
328	  uint32_t remaining = len;
329	  uint32_t timeout;
330	
331	  while (remaining > 0)
332	    {
333	      timeout = 20000000u;
334	      while ((REG32(QSPI_SR) & QSPI_SR_FTF) == 0)
335	        {
336	          if ((REG32(QSPI_SR) & QSPI_SR_TEF) != 0)
337	            {
338	              return -1;
339	            }
340	
341	          if (timeout-- == 0)
342	            {
343	              return -1;
344	            }
345	        }
346	
347	      *dr = *buf++;
348	      remaining--;
349	    }
350	
351	  if (qspi_wait_tcf() != 0)
352	    {
353	      return -1;
354	    }
355	
356	  qspi_clear_flags();
357	  return 0;
358	}
