360	static int qspi_indirect_read(uint8_t inst, uint32_t addr, int has_addr,
361	                              uint32_t dummy, uint8_t *buf, uint32_t len)
362	{
363	  uint32_t ccr;
364	
365	  if (len == 0)
366	    {
367	      return -1;
368	    }
369	
370	  qspi_clear_flags();
371	  REG32(QSPI_DLR) = len - 1u;
372	
373	  ccr = (uint32_t)inst | QSPI_CCR_IMODE_1 | QSPI_CCR_DMODE_1 |
374	        QSPI_CCR_FMODE_INDRD | QSPI_CCR_DCYC(dummy);
375	  if (has_addr)
376	    {
377	      ccr |= QSPI_CCR_ADMODE_1 | QSPI_CCR_ADSIZE_32;
378	    }
379	
380	  REG32(QSPI_CCR) = ccr;
381	  if (has_addr)
382	    {
383	      REG32(QSPI_AR) = addr;
384	    }
385	
386	  if (qspi_read_data(buf, len) != 0)
387	    {
388	      qspi_abort();
389	      qspi_clear_flags();
390	      return -1;
391	    }
392	
393	  qspi_wait_idle();
394	  return 0;
395	}
