397	static int qspi_indirect_write(uint8_t inst, uint32_t addr,
398	                               const uint8_t *buf, uint32_t len)
399	{
400	  if (len == 0)
401	    {
402	      return -1;
403	    }
404	
405	  qspi_clear_flags();
406	  REG32(QSPI_DLR) = len - 1u;
407	  REG32(QSPI_CCR) = (uint32_t)inst | QSPI_CCR_IMODE_1 |
408	                    QSPI_CCR_ADMODE_1 | QSPI_CCR_ADSIZE_32 |
409	                    QSPI_CCR_DMODE_1;
410	  REG32(QSPI_AR) = addr;
411	
412	  if (qspi_write_data(buf, len) != 0)
413	    {
414	      qspi_abort();
415	      qspi_clear_flags();
416	      return -1;
417	    }
418	
419	  qspi_wait_idle();
420	  return 0;

421	}
