426	  REG32(QSPI_CCR) = (uint32_t)inst | QSPI_CCR_IMODE_1;
427	
428	  if (qspi_wait_tcf() != 0)
429	    {
430	      qspi_abort();
431	      qspi_clear_flags();
432	      return -1;
433	    }
434	
435	  qspi_wait_idle();
436	  qspi_clear_flags();
437	  return 0;
