459	static int install_range(uint32_t address, uint32_t len)
460	{
461	  return address>=APP_B_BASE && address<APP_B_BASE+APP_SLOT_SIZE &&
462	         len>0 && len<=APP_B_BASE+APP_SLOT_SIZE-address;
463	}
464	
465	static int install_ready(void)
466	{
467	  uint32_t i;
468	  uint8_t status[2];
469	  for (i=0; i<200000u; i++)
470	    {
471	      if (qspi_indirect_read(0x05,0,0,0,status,2)) return -1;
472	      if (!((status[0]|status[1])&1u)) return 0;
473	    }
474	  return -1;
475	}
476	
477	static int install_write_enable(void)
478	{
479	  uint8_t status[2];
480	  if (install_ready() || qspi_no_data(0x06) ||
481	      qspi_indirect_read(0x05,0,0,0,status,2)) return -1;
482	  return (status[0]&2u) && (status[1]&2u) ? 0 : -1;
483	}
484	
485	static int install_erase(void *ctx, uint32_t address, uint32_t len)
486	{
487	  uint8_t id[6];
488	  (void)ctx;
489	  if (!install_range(address,len) || len!=VG_OTA_ERASE_BYTES ||
490	      address%VG_OTA_ERASE_BYTES) return -1;
491	  qspi_abort();
492	  qspi_select_dual();
493	  /* DFM 将两颗器件的字节交错；ID/状态也必须读取偶数字节。 */
494	  if (qspi_indirect_read(0x9f,0,0,0,id,6) ||
495	      id[0]!=0x20 || id[1]!=0x20 || id[2]!=0xba || id[3]!=0xba ||
496	      id[4]!=0x20 || id[5]!=0x20) return -1;
497	  if (install_write_enable() ||
498	      qspi_no_data_addr(0x21,address-APP_A_BASE)) return -1;
499	  return install_ready();
500	}
501	
502	static int install_program(void *ctx, uint32_t address,
503	                            const uint8_t *data, uint32_t len)
504	{
505	  uint8_t page[VG_OTA_PROGRAM_BYTES];
506	  uint32_t i;
507	  (void)ctx;
508	  if (!data || !install_range(address,VG_OTA_PROGRAM_BYTES) ||
509	      !len || len>sizeof(page) || address%VG_OTA_PROGRAM_BYTES) return -1;
510	  for (i=0; i<sizeof(page); i++) page[i]=i<len ? data[i] : 0xff;
511	  qspi_abort();
512	  qspi_select_dual();
513	  if (install_write_enable() ||
514	      qspi_indirect_write(0x12,address-APP_A_BASE,page,sizeof(page))) return -1;
515	  return install_ready();
516	}
517	
518	static int install_read_flash(void *ctx, uint32_t address,
519	                               uint8_t *data, uint32_t len)
520	{
521	  uint32_t i;
522	  (void)ctx;
523	  if (!data || !install_range(address,len)) return -1;
524	  qspi_enter_memory_mapped();
525	  for (i=0; i<len; i++) data[i]=*(volatile uint8_t *)(uintptr_t)(address+i);
526	  return 0;
527	}
