538	{
539	  static const char hex[]="0123456789abcdef";
540	  volatile const uint8_t *uid=(volatile const uint8_t *)0x1ff1e800u;
541	  uint32_t i;
542	  out[0]='v'; out[1]='g'; out[2]='-';
