551	static int qspi_scratch_one(uint32_t flash, uint32_t addr)
552	{
553	  volatile struct vg_ota_mbox *mbox = VG_OTA_MBOX;
554	  volatile uint8_t *mem;
555	  uint8_t pattern[256];
556	  uint8_t readback[256];
557	  uint32_t i;
558	
559	  qspi_abort();
560	  qspi_select_flash(flash);
561	
562	  for (i = 0; i < sizeof(pattern); i++)
563	    {
564	      pattern[i] = (uint8_t)(0xa5u ^ i ^ (addr >> 16));
565	    }
566	
567	  if (qspi_no_data(0x06) != 0)
568	    {
569	      return 1;
570	    }

571	
572	  if (qspi_no_data_addr(0x21, addr) != 0)
573	    {
574	      return 2;
575	    }
576	
577	  /* A 4 KiB sector erase is typically tens of milliseconds; allow ample
578	   * time because this diagnostic does not poll the status register.
579	   */
580	
581	  delay_cycles(200000000u);
582	
583	  qspi_enter_memory_mapped();
584	  mem = (volatile uint8_t *)(0x90000000u + addr);
585	  for (i = 0; i < sizeof(readback); i++)
586	    {
587	      readback[i] = mem[i];
588	    }
589	
590	  for (i = 0; i < sizeof(readback); i++)
591	    {
592	      if (readback[i] != 0xffu)
593	        {
594	          mbox->fail_index = i;
595	          mbox->fail_got = readback[i];
596	          mbox->fail_want = 0xffu;
597	          return 5;
598	        }
599	    }
600	
601	  qspi_abort();
602	  qspi_select_flash(flash);
603	
604	  if (qspi_no_data(0x06) != 0)
605	    {
606	      return 6;
607	    }
608	
609	  if (qspi_indirect_write(0x12, addr, pattern, sizeof(pattern)) != 0)
610	    {
611	      return 7;
612	    }
613	
614	  delay_cycles(20000000u);
615	
616	  qspi_enter_memory_mapped();
617	  mem = (volatile uint8_t *)(0x90000000u + addr);
618	  for (i = 0; i < sizeof(readback); i++)
619	    {
620	      readback[i] = mem[i];
621	    }
622	
623	  for (i = 0; i < sizeof(readback); i++)
624	    {
625	      if (readback[i] != pattern[i])
626	        {
627	          mbox->fail_index = i;
628	          mbox->fail_got = readback[i];
629	          mbox->fail_want = pattern[i];
630	          return 10;
631	        }
632	    }
633	
634	  return 0;
635	}
