637	static int qspi_probe_run(void)
638	{
639	  volatile struct vg_ota_mbox *mbox = VG_OTA_MBOX;
640	  uint8_t id[3];
641	  uint32_t fsize;
642	  int has_flash2 = 0;
643	  int ret;
644	
645	  mbox->state = VG_OTA_MBOX_RUNNING;
646	  mbox->run_seq = mbox->seq;
647	  mbox->error = 0;
648	  mbox->jedec1 = 0;
649	  mbox->jedec2 = 0;
650	  mbox->capacity = 0;
651	  mbox->erase_size = 4096;
652	  mbox->write_size = 256;
653	  mbox->sr = 0;
654	  mbox->cr = 0;
655	  mbox->ccr = 0;
656	  mbox->dcr = 0;
657	  mbox->raw1 = 0;
658	  mbox->raw2 = 0;
659	  mbox->fail_index = 0;
660	  mbox->fail_got = 0;
661	  mbox->fail_want = 0;
662	
663	  qspi_select_flash(0);
664	  if (qspi_indirect_read(0x9f, 0, 0, 0, id, sizeof(id)) != 0)
665	    {
666	      mbox->error = 1;
667	      goto fail;
668	    }
669	
670	  mbox->raw1 = ((uint32_t)id[0] << 16) |
671	               ((uint32_t)id[1] << 8) | id[2];
672	  mbox->jedec1 = ((uint32_t)id[0] << 16) |
673	                 ((uint32_t)id[2] << 8) | id[1];
674	
675	  qspi_select_flash(1);
676	  if (qspi_indirect_read(0x9f, 0, 0, 0, id, sizeof(id)) != 0)
677	    {
678	      /* The second device may not be populated.  Its absence is a valid
679	       * P0 result; keep the single-flash capacity and test flash 1.
680	       */
681	
682	      qspi_abort();
683	      qspi_clear_flags();
684	      has_flash2 = 0;
685	    }
686	  else
687	    {
688	      mbox->raw2 = ((uint32_t)id[0] << 16) |
689	                   ((uint32_t)id[1] << 8) | id[2];
690	      mbox->jedec2 = ((uint32_t)id[0] << 16) |
691	                     ((uint32_t)id[2] << 8) | id[1];
692	      has_flash2 = 1;
693	    }
694	
695	  fsize = (REG32(QSPI_DCR) >> 16) & 0x1fu;
696	  mbox->capacity = 1u << fsize;
697	  if (has_flash2)
698	    {
699	      mbox->capacity <<= 1;
700	    }
701	
702	  ret = qspi_scratch_one(0, 0x03ff0000u);
703	  if (ret != 0)
704	    {
705	      mbox->error = 10u + (uint32_t)ret;
706	      goto fail;
707	    }
708	
709	  if (has_flash2)
710	    {
711	      ret = qspi_scratch_one(1, 0x03ff0000u);
712	      if (ret != 0)
713	        {
714	          mbox->error = 20u + (uint32_t)ret;
715	          goto fail;
716	        }
717	    }
718	
719	  qspi_select_dual();
720	  mbox->state = VG_OTA_MBOX_OK;

721	  return 0;
722	
723	fail:
724	  mbox->sr = REG32(QSPI_SR);
725	  mbox->cr = REG32(QSPI_CR);
726	  mbox->ccr = REG32(QSPI_CCR);
727	  mbox->dcr = REG32(QSPI_DCR);
728	  qspi_select_dual();
729	  mbox->state = VG_OTA_MBOX_FAIL;
730	  return -1;
731	}
