733	static int valid_sram(uint32_t value)
734	{
735	  /* Cortex-M loads the initial MSP from the vector table and requires a
736	   * word-aligned value.  NuttX may place its early stack on a 4-byte boundary
737	   * before establishing the ABI-aligned task stack.
738	   */
739	
740	  return value >= SRAM_BASE && value < SRAM_LIMIT && (value & 3u) == 0;
741	}
742	
743	static int valid_entry(uint32_t base, uint32_t value)
744	{
745	  uint32_t addr = value & ~1u;
746	
747	  return addr >= base && addr < base + APP_SLOT_SIZE && (value & 1u) != 0;
748	}
749	
750	static int valid_vector(uint32_t base)
751	{
752	  uint32_t stack = REG32(base);
753	  uint32_t entry = REG32(base + 4u);
754	
755	  return valid_sram(stack) && valid_entry(base, entry);
756	}
