758	__attribute__((naked, noreturn))
759	static void jump_to_image(uint32_t, uint32_t)
760	{
761	  __asm__ volatile
762	    (
763	      "msr msp, r0\n"
764	      "msr psp, r0\n"
765	      "movs r0, #0\n"
766	      "msr control, r0\n"
767	      "isb\n"
768	      "bx r1\n"
769	    );
770	}
