835	static void boot_select(void)
836	{
837	  struct vg_ota_boot_decision d;
838	  uint32_t target = APP_A_BASE;
839	  uint32_t slot = VG_OTA_BCB_SLOT_A;
840	  uint32_t reason;
841	  char device_id[32];
842	
843	  if (vg_emmc_init() == 0)
844	    {
845	      vg_ota_boot_decide(vg_emmc_read_blocks, 0, vg_emmc_sector_count(), &d);
846	      if (d.reason==VG_OTA_BOOT_REASON_A_PENDING)
847	        {
848	          struct vg_ota_install_ports p={0};
849	          hardware_device_id(device_id);
850	          p.read=vg_emmc_read_blocks; p.sectors=vg_emmc_sector_count();
851	          p.write_sector=vg_emmc_write_sector; p.sync=vg_emmc_sync;
852	          p.erase=install_erase; p.program=install_program;
853	          p.read_flash=install_read_flash; p.device_id=device_id;
854	          p.allow_fixture=VG_OTA_STUB_FIXTURES;
855	          p.progress=install_progress;
856	          vg_ota_install_pending(&p,&d);
857	          qspi_abort();
858	          qspi_select_dual();
859	          install_ready();
860	          qspi_enter_memory_mapped();
861	        }
862	      if (d.emmc_error == 0 && vg_emmc_error() != 0)
863	        {
864	          d.emmc_error = vg_emmc_error();
865	        }
866	    }
867	  else
868	    {
869	      zero_boot_decision(&d);
870	      d.emmc_error = vg_emmc_error();

871	    }
872	
873	  reason = d.reason;
874	
875	  if (d.slot == VG_OTA_BCB_SLOT_B)
876	    {
877	      if (valid_vector(APP_B_BASE))
878	        {
879	          target = APP_B_BASE;
880	          slot = VG_OTA_BCB_SLOT_B;
881	        }
882	      else
883	        {
884	          target = APP_A_BASE;
885	          slot = VG_OTA_BCB_SLOT_A;
886	          reason = VG_OTA_BOOT_REASON_A_IMAGE_INVALID;
887	        }
888	    }
889	
890	  if (!valid_vector(target))
891	    {
892	      publish_boot(&d, VG_OTA_BCB_SLOT_A, VG_OTA_BOOT_REASON_A_SAFE_STOP);
893	      Default_Handler();
894	    }
895	
896	  publish_boot(&d, slot, reason);
897	
898	  REG32(SCB_VTOR) = target;
899	  __asm__ volatile ("dsb 0xf" ::: "memory");
900	  __asm__ volatile ("isb 0xf" ::: "memory");
901	  jump_to_image(REG32(target), REG32(target + 4u));
902	}
