232	static int fixture_write(const char *name, uint32_t size, uint32_t seed)
233	{
234	  char path[64];
235	  uint8_t buf[256];
236	  uint32_t off;
237	  int fd;
238	
239	  if (fixture_name_ok(name) == 0)
240	    {
241	      printf("vgota: fixture invalid name %s\n", name);
242	      return 1;
243	    }
244	
245	  if (size > VG_OTA_MAX_FIXTURE_SIZE)
246	    {
247	      printf("vgota: fixture size %" PRIu32 " exceeds %u\n",
248	             size, VG_OTA_MAX_FIXTURE_SIZE);
249	      return 1;
250	    }
251	
252	  if (mkdir(VG_OTA_DIR, 0755) < 0 && errno != EEXIST)
253	    {
254	      printf("vgota: fixture mkdir %s ERR=%d\n", VG_OTA_DIR, errno);
255	      return 1;
256	    }
257	
258	  snprintf(path, sizeof(path), "%s/%s", VG_OTA_DIR, name);
259	  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
260	  if (fd < 0)
261	    {
262	      printf("vgota: fixture open %s ERR=%d\n", path, errno);
263	      return 1;
264	    }
265	
266	  for (off = 0; off < size; )
267	    {
268	      uint32_t chunk = size - off;
269	      uint32_t done = 0;
270	      uint32_t i;
271	
272	      if (chunk > sizeof(buf))
273	        {
274	          chunk = sizeof(buf);
275	        }
276	
277	      for (i = 0; i < chunk; i++)
278	        {
279	          buf[i] = (uint8_t)(seed + off + i);
280	        }
281	
282	      while (done < chunk)
283	        {
284	          ssize_t written = write(fd, buf + done, chunk - done);
285	          if (written <= 0)
286	            {
287	              printf("vgota: fixture write %s ERR=%d\n", path, errno);
288	              close(fd);
289	              return 1;
290	            }
291	
292	          done += (uint32_t)written;
293	        }
294	
295	      off += chunk;
296	    }
297	
298	  if (fsync(fd) < 0)
299	    {
300	      printf("vgota: fixture fsync %s ERR=%d\n", path, errno);

301	      close(fd);
302	      return 1;
303	    }
304	
305	  close(fd);
306	  printf("vgota: fixture write %s size=%" PRIu32 " seed=%" PRIu32 "\n",
307	         name, size, seed);
308	  return 0;
309	}
