408	static int fixture_read(const char *name, uint8_t *data, uint32_t size)
409	{
410	  char path[64];
411	  uint32_t done = 0;
412	  int fd;
413	
414	  snprintf(path, sizeof(path), "%s/%s", VG_OTA_DIR, name);
415	  fd = open(path, O_RDONLY);
416	  if (fd < 0)
417	    {
418	      return -errno;
419	    }
420	
421	  while (done < size)
422	    {
423	      ssize_t got = read(fd, data + done, size - done);
424	
425	      if (got == 0)
426	        {
427	          close(fd);
428	          return -EINVAL;
429	        }
430	
431	      if (got < 0)
432	        {
433	          close(fd);
434	          return -EIO;
435	        }
436	
437	      done += (uint32_t)got;
438	    }
439	
440	  close(fd);
441	  return 0;
442	}
