570	{
571	  struct vg_ota_bcb bcb;
572	  uint8_t buf[VG_OTA_BCB_FILE_BYTES];
573	  const char *version = "0.2.0";
574	  const char *task = "FIXTURE";
575	  const char *name;
576	  uint32_t index;
577	  uint32_t i;
578	  int ret;
579	
580	  if (argc < 9 || argc > 11)
581	    {
582	      usage();
583	      return 1;
584	    }
585	
586	  if (fixture_bcb_index(argv[4], &index, &name) != 0)
587	    {
588	      return 1;
589	    }
590	
591	  (void)index;
592	  memset(&bcb, 0, sizeof(bcb));
593	
594	  if (fixture_bcb_state(argv[5], &bcb.state) != 0 ||
595	      fixture_bcb_slot(argv[6], &bcb.slot) != 0 ||
596	      parse_u32(argv[7], &bcb.seq) != 0 ||
597	      parse_u32(argv[8], &bcb.image_size) != 0)
598	    {
599	      return 1;
600	    }

601	
602	  if (argc >= 10)
603	    {
604	      version = argv[9];
605	    }
606	
607	  if (argc >= 11)
608	    {
609	      task = argv[10];
610	    }
611	
612	  if (strlen(version) >= sizeof(bcb.version) ||
613	      strlen(task) >= sizeof(bcb.task_id))
614	    {
615	      printf("vgota: fixture bcb version or task too long\n");
616	      return 1;
617	    }
618	
619	  snprintf(bcb.version, sizeof(bcb.version), "%s", version);
620	  snprintf(bcb.task_id, sizeof(bcb.task_id), "%s", task);
621	
622	  for (i = 0; i < sizeof(bcb.sha256); i++)
623	    {
624	      bcb.sha256[i] = (uint8_t)(0x5au ^ i);
625	    }
626	
627	  ret = vg_ota_bcb_encode(&bcb, buf, sizeof(buf));
628	  if (ret != 0)
629	    {
630	      printf("vgota: fixture bcb encode ERR=%d\n", -ret);
631	      return 1;
632	    }
633	
634	  if (fixture_store(name, buf, sizeof(buf)) != 0)
635	    {
636	      return 1;
637	    }
638	
639	  printf("vgota: fixture %s seq=%" PRIu32 " state=%s slot=%s"
640	         " size=%" PRIu32 " version=%s task=%s\n",
641	         name, bcb.seq, vg_ota_bcb_state_name(bcb.state),
642	         vg_ota_bcb_slot_name(bcb.slot), bcb.image_size, bcb.version,
643	         bcb.task_id);
644	  return 0;
645	}
