740	static int fixture_image_hash(uint8_t digest[32])
741	{
742	  struct vg_ota_sha256 sha;
743	  uint8_t buf[512];
744	  ssize_t n;
745	  int fd=open(VG_OTA_DIR "/IMAGE.BIN",O_RDONLY);
746	  if (fd<0) return 1;
747	  vg_ota_sha256_init(&sha);
748	  while ((n=read(fd,buf,sizeof(buf)))>0)
749	    vg_ota_sha256_update(&sha,buf,(uint32_t)n);
750	  close(fd);

751	  if (n<0) return 1;
752	  vg_ota_sha256_final(&sha,digest);
753	  return 0;
754	}
