756	/* ST-Link 只把传输副本写到固定测试窗口，B 槽交给 boot stub 安装。 */
757	static int fixture_stage(int argc, char *argv[])
758	{
759	  struct vg_ota_manifest m;
760	  struct vg_ota_bcb b;
761	  uint8_t buf[4096];
762	  uint32_t size, seq, off, n, i;
763	  volatile const uint8_t *src=(volatile const uint8_t *)0x91000000u;
764	  int fd;
765	  if ((argc!=5 && argc!=6) || vg_fw_slot()!='A' ||
766	      parse_u32(argv[3],&size) || parse_u32(argv[4],&seq) ||
767	      size<8 || size>VG_OTA_IMAGE_MAX_BYTES) return 1;
768	  for (i=0; i<8; i++) buf[i]=src[i];
769	  if (!vg_ota_image_vector_valid(buf,size))
770	    { printf("vgota: fixture transport vector invalid\n"); return 1; }
771	  memset(&m,0,sizeof(m));
772	  snprintf(m.task_id,sizeof(m.task_id),"%s",argc==6 ? argv[5] : "T04-FIXTURE");
773	  if (argc==6 && strlen(argv[5])>=sizeof(m.task_id)) return 1;
774	  m.slot=VG_OTA_BCB_SLOT_B; m.image_size=size;
775	  m.flags=VG_OTA_MANIFEST_FIXTURE; m.issued_at=1; m.expires_at=UINT64_MAX;
776	  snprintf(m.version,sizeof(m.version),"%s",vg_fw_version());
777	  snprintf(m.device_id,sizeof(m.device_id),"%s",vg_device_id());
778	  snprintf(m.model,sizeof(m.model),"%s",VG_OTA_MODEL);
779	  snprintf(m.key_id,sizeof(m.key_id),"fixture");
780	  if (mkdir(VG_OTA_DIR,0755)<0 && errno!=EEXIST) return 1;
781	  fd=open(VG_OTA_DIR "/IMAGE.BIN",O_WRONLY|O_CREAT|O_TRUNC,0644);
782	  if (fd<0) return 1;
783	  for (off=0; off<size; off+=n)
784	    {
785	      n=size-off; if (n>sizeof(buf)) n=sizeof(buf);
786	      for (i=0; i<n; i++) buf[i]=src[off+i];
787	      if (write(fd,buf,n)!=(ssize_t)n) { close(fd); return 1; }
788	    }
789	  if (fsync(fd)<0) { close(fd); return 1; }
790	  close(fd);
791	  if (fixture_image_hash(m.sha256) || vg_ota_manifest_encode(&m,buf) ||
792	      fixture_store("MANIFEST.BIN",buf,512)) return 1;
793	  memset(&b,0,sizeof(b));
794	  b.slot=VG_OTA_BCB_SLOT_B; b.image_size=size; b.state=VG_OTA_BCB_STATE_FAILED;
795	  snprintf(b.version,sizeof(b.version),"%s",m.version);
796	  snprintf(b.task_id,sizeof(b.task_id),"%s",m.task_id);
797	  memcpy(b.sha256,m.sha256,32);
798	  b.seq=seq-1u;
799	  if (vg_ota_bcb_encode(&b,buf,sizeof(buf)) ||
800	      fixture_store("BCB0.BIN",buf,sizeof(buf))) return 1;
801	  b.seq=seq-2u;
802	  if (vg_ota_bcb_encode(&b,buf,sizeof(buf)) ||
803	      fixture_store("BCB1.BIN",buf,sizeof(buf))) return 1;
804	  sync();
805	  printf("vgota: fixture staged bytes=%" PRIu32 " task=%s sha=%02x%02x%02x%02x; not armed\n",
806	         size,m.task_id,m.sha256[0],m.sha256[1],m.sha256[2],m.sha256[3]);
807	  return 0;
808	}
