810	static int fixture_arm(void)
811	{
812	  struct vg_ota_manifest m;
813	  struct vg_ota_bcb b, other;
814	  uint8_t buf[4096], digest[32];
815	  uint32_t i, held=0;
816	  const char *target;
817	  if (vg_fw_slot()!='A' || fixture_read("MANIFEST.BIN",buf,512) ||
818	      vg_ota_manifest_decode(buf,512,&m) || m.flags!=VG_OTA_MANIFEST_FIXTURE ||
819	      fixture_read("BCB0.BIN",buf,4096) || vg_ota_bcb_decode(buf,4096,&b) ||
820	      fixture_read("BCB1.BIN",buf,4096) || vg_ota_bcb_decode(buf,4096,&other))
821	    return 1;
822	  if (vg_ota_bcb_seq_newer(other.seq,b.seq))
823	    { b=other; target="BCB0.BIN"; }
824	  else target="BCB1.BIN";
825	  b.seq++; b.state=VG_OTA_BCB_STATE_PENDING;
826	  b.flags=VG_OTA_BCB_LOCAL_CONFIRMED; b.trial_count=0;
827	  if (vg_ota_manifest_bind(&m,&b,vg_device_id(),1)) return 1;
828	  printf("vgota: fixture local confirmation version=%s task=%s bytes=%" PRIu32 "\n",
829	         m.version,m.task_id,m.image_size);
830	  printf("vgota: release board USER button, then hold it for 2 seconds within 60 seconds\n");
831	  fflush(stdout);
832	  /* 必须先释放再按下，串口命令和调用方不能代替本机按键事件。 */
833	  for (i=0; i<600 && board_buttons()!=0; i++) usleep(100000);
834	  if (i==600) return 1;
835	  for (i=0; i<600 && held<20; i++)
836	    {
837	      held=board_buttons()!=0 ? held+1 : 0;
838	      usleep(100000);
839	    }
840	  if (held<20) { printf("vgota: fixture local confirmation timed out\n"); return 1; }
841	  if (fixture_image_hash(digest) || memcmp(digest,m.sha256,32) ||
842	      vg_ota_bcb_encode(&b,buf,sizeof(buf)) ||
843	      fixture_store(target,buf,sizeof(buf))) return 1;
844	  sync();
845	  printf("vgota: fixture pending locally confirmed seq=%" PRIu32 "\n",b.seq);
846	  return 0;
847	}
