6	static uint32_t r32(const uint8_t *p)
7	{
8	  return (uint32_t)p[0] | ((uint32_t)p[1]<<8) |
9	         ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24);
10	}
