12	int vg_ota_image_vector_valid(const uint8_t v[8], uint32_t size)
13	{
14	  uint32_t sp=r32(v), pc=r32(v+4), addr=pc&~1u;
15	  int ram=(sp>0x20000000u && sp<=0x20020000u) ||
16	          (sp>0x24000000u && sp<=0x24080000u) ||
17	          (sp>0x30000000u && sp<=0x30048000u) ||
18	          (sp>0x38000000u && sp<=0x38010000u);
19	  return size>=8 && size<=VG_OTA_IMAGE_MAX_BYTES && ram && !(sp&3u) &&
20	         (pc&1u) && addr>=VG_OTA_SLOT_B_BASE &&
21	         addr-VG_OTA_SLOT_B_BASE<size;
22	}
