31	/* 只更新已有 BCB 的首扇区，CRC 覆盖的头部完全位于该扇区。
32	 * 每次都同步并回读；另一份有效 FAILED 在 trial 提交期间保持不动。
33	 */
34	static int store_bcb(const struct vg_ota_install_ports *p,
35	                      struct vg_ota_fat_volume *v,
36	                      const struct vg_ota_fat_entry *e,
37	                      const struct vg_ota_bcb *b)
38	{
39	  uint8_t buf[4096], check[512];
40	  uint32_t sector;
41	  if (vg_ota_bcb_encode(b,buf,sizeof(buf)) ||
42	      vg_ota_fat_file_sector(v,e,0,&sector) ||
43	      p->write_sector(p->ctx,sector,buf) || p->sync(p->ctx) ||
44	      p->read(p->ctx,sector,check,1) || memcmp(buf,check,512)) return -EIO;
45	  return 0;
46	}
