48	static int hash_image(const struct vg_ota_install_ports *p,
49	                       struct vg_ota_fat_volume *v,
50	                       const struct vg_ota_fat_entry *e, uint8_t digest[32],
51	                       int from_flash)
52	{
53	  struct vg_ota_sha256 sha;
54	  uint8_t buf[4096];
55	  uint32_t off, n;
56	  vg_ota_sha256_init(&sha);
57	  for (off=0; off<e->size; off+=n)
58	    {
59	      n=e->size-off; if (n>sizeof(buf)) n=sizeof(buf);
60	      if (from_flash ? p->read_flash(p->ctx,VG_OTA_SLOT_B_BASE+off,buf,n) :
61	          vg_ota_fat_read(v,e,off,buf,n)) return -EIO;
62	      vg_ota_sha256_update(&sha,buf,n);
63	    }
64	  vg_ota_sha256_final(&sha,digest);
65	  return 0;
66	}
