68	static int install(const struct vg_ota_install_ports *p,
69	                     struct vg_ota_boot_decision *d)
70	{
71	  static const char names[2][11]={"BCB0    BIN","BCB1    BIN"};
72	  struct vg_ota_fat_volume vol;
73	  struct vg_ota_fat_entry dir, entries[2], image, manifest;
74	  struct vg_ota_manifest m;
75	  struct vg_ota_bcb b, changed;
76	  struct vg_ota_sha256 sha;
77	  uint8_t blocks[2][4096], buf[4096], digest[32], other_digest[32];
78	  uint32_t which, off, n, i, lba[2], erase_len;
79	  int valid0, valid1;
80	
81	  stage(p,d,VG_OTA_INSTALL_METADATA,0);
82	  if (vg_ota_fat_mount(&vol,p->read,p->ctx,p->sectors) ||
83	      vg_ota_fat_find(&vol,"VGOTA      ",0,&dir) || !(dir.attr&0x10))
84	    return -EINVAL;
85	  for (i=0; i<2; i++)
86	    {
87	      if (vg_ota_fat_find(&vol,names[i],dir.first_cluster,&entries[i]) ||
88	          entries[i].attr&0x10 || entries[i].size!=4096 ||
89	          vg_ota_fat_read(&vol,&entries[i],0,blocks[i],4096) ||
90	          vg_ota_fat_file_sector(&vol,&entries[i],0,&lba[i])) return -EINVAL;
91	    }
92	  if (lba[0]==lba[1] ||
93	      vg_ota_bcb_select(blocks[0],4096,1,blocks[1],4096,1,&b,&which,
94	                         &valid0,&valid1) ||
95	      b.seq!=d->bcb_seq || which!=d->bcb_which ||
96	      b.state!=VG_OTA_BCB_STATE_PENDING) return -EINVAL;
97	  if (vg_ota_fat_find(&vol,"MANIFESTBIN",dir.first_cluster,&manifest) ||
98	      manifest.attr&0x10 || manifest.size!=512 ||
99	      vg_ota_fat_read(&vol,&manifest,0,buf,512) ||
100	      vg_ota_manifest_decode(buf,512,&m) ||

101	      vg_ota_manifest_bind(&m,&b,p->device_id,p->allow_fixture)) return -EINVAL;
102	  if (vg_ota_fat_find(&vol,"IMAGE   BIN",dir.first_cluster,&image) ||
103	      image.attr&0x10 || image.size!=m.image_size ||
104	      vg_ota_fat_read(&vol,&image,0,buf,8) ||
105	      !vg_ota_image_vector_valid(buf,image.size)) return -EINVAL;
106	
107	  /* BCB 首扇区不能与镜像、manifest、目录或另一份 BCB 的任何簇重合。 */
108	  for (i=0; i<2; i++)
109	    {
110	      const struct vg_ota_fat_entry *files[3]={&image,&manifest,&entries[1-i]};
111	      uint32_t j, step=vol.info.sectors_per_cluster*512u;
112	      if (entries[i].first_cluster==dir.first_cluster ||
113	          entries[i].first_cluster==vol.info.root_cluster) return -EINVAL;
114	      for (j=0; j<3; j++)
115	        for (off=0; off<files[j]->size; off+=step)
116	          {
117	            uint32_t sector;
118	            if (vg_ota_fat_file_sector(&vol,files[j],off,&sector) ||
119	                sector==lba[i]) return -EINVAL;
120	          }
121	    }
122	  stage(p,d,VG_OTA_INSTALL_IMAGE,0);
123	  if (hash_image(p,&vol,&image,digest,0) || memcmp(digest,m.sha256,32))
124	    return -EBADMSG;
125	
126	  /* 先持久化更高序号 FAILED，再允许任何 QSPI 擦写。断电后不自动重装。
127	   * 最终 TRIAL 写回原 pending 文件；撕裂写入时仍有另一份 FAILED 可选。
128	   */
129	  stage(p,d,VG_OTA_INSTALL_FENCE,0);
130	  changed=b; changed.seq=b.seq+1u; changed.state=VG_OTA_BCB_STATE_FAILED;
131	  if (store_bcb(p,&vol,&entries[1-which],&changed)) return -EIO;
132	  stage(p,d,VG_OTA_INSTALL_ERASE,0);
133	  erase_len=(image.size+VG_OTA_ERASE_BYTES-1u)&~(VG_OTA_ERASE_BYTES-1u);
134	  if (erase_len>VG_OTA_SLOT_BYTES) return -EINVAL;
135	  for (off=0; off<erase_len; off+=VG_OTA_ERASE_BYTES)
136	    {
137	      stage(p,d,VG_OTA_INSTALL_ERASE,off);
138	      if (p->erase(p->ctx,VG_OTA_SLOT_B_BASE+off,VG_OTA_ERASE_BYTES))
139	        return -EIO;
140	    }
141	  vg_ota_sha256_init(&sha);
142	  for (off=0; off<image.size; off+=n)
143	    {
144	      n=image.size-off; if (n>sizeof(buf)) n=sizeof(buf);
145	      stage(p,d,VG_OTA_INSTALL_PROGRAM,off);
146	      if (vg_ota_fat_read(&vol,&image,off,buf,n)) return -EIO;
147	      vg_ota_sha256_update(&sha,buf,n);
148	      for (i=0; i<n; i+=VG_OTA_PROGRAM_BYTES)
149	        {
150	          uint32_t count=n-i;
151	          if (count>VG_OTA_PROGRAM_BYTES) count=VG_OTA_PROGRAM_BYTES;
152	          if (p->program(p->ctx,VG_OTA_SLOT_B_BASE+off+i,buf+i,count))
153	            return -EIO;
154	        }
155	    }
156	  vg_ota_sha256_final(&sha,other_digest);
157	  if (memcmp(digest,other_digest,32)) return -EBADMSG;
158	  stage(p,d,VG_OTA_INSTALL_READBACK,image.size);
159	  if (hash_image(p,&vol,&image,other_digest,1) || memcmp(digest,other_digest,32))
160	    return -EBADMSG;
161	  stage(p,d,VG_OTA_INSTALL_TRIAL,image.size);
162	  changed=b; changed.seq=b.seq+2u; changed.state=VG_OTA_BCB_STATE_TRIAL;
163	  changed.trial_count=1;
164	  if (store_bcb(p,&vol,&entries[which],&changed)) return -EIO;
165	  d->slot=VG_OTA_BCB_SLOT_B; d->reason=VG_OTA_BOOT_REASON_B_INSTALLED;
166	  d->bcb_seq=changed.seq; d->bcb_state=changed.state;
167	  d->bcb_valid0=1; d->bcb_valid1=1;
168	  stage(p,d,VG_OTA_INSTALL_DONE,image.size);
169	  return 0;
170	}
