95	int vg_fw_version_valid(const char *version)
96	{
97	  const char *p = version;
98	  int part;
99	
100	  if (p == NULL)
101	    {
102	      return 0;
103	    }
104	
105	  for (part = 0; part < 3; part++)
106	    {
107	      const char *start = p;
108	
109	      while (*p >= '0' && *p <= '9')
110	        {
111	          p++;
112	        }
113	
114	      if (p == start)
115	        {
116	          return 0;
117	        }
118	
119	      if (part < 2)
120	        {
121	          if (*p != '.')
122	            {
123	              return 0;
124	            }
125	
126	          p++;
127	        }
128	    }
129	
130	  return *p == '\0';
131	}
