1	MEMORY
2	{
3	  flash (rx)  : ORIGIN = 0x08000000, LENGTH = 128K
4	  ram   (rwx) : ORIGIN = 0x24000000, LENGTH = 512K
5	}
6	
7	_estack = ORIGIN(ram) + LENGTH(ram);
8	
9	OUTPUT_ARCH(arm)
10	ENTRY(Reset_Handler)
11	
12	SECTIONS
13	{
14	  .vectors ORIGIN(flash) :
15	  {
16	    KEEP(*(.vectors))
17	  } > flash
18	
19	  .text :
20	  {
21	    *(.text .text.*)
22	    *(.rodata .rodata.*)
23	    . = ALIGN(4);
24	    _etext = .;
25	  } > flash
26	
27	  .data :
28	  {
29	    _sdata = .;
30	    *(.data .data.*)
31	    . = ALIGN(4);
32	    _edata = .;
33	  } > ram AT > flash
34	
35	  _sidata = LOADADDR(.data);
36	
37	  .bss (NOLOAD) :
38	  {
39	    _sbss = .;
40	    *(.bss .bss.*)
41	    *(COMMON)
42	    . = ALIGN(4);
43	    _ebss = .;
44	  } > ram
45	
46	  /DISCARD/ :
47	  {
48	    *(.comment)
49	    *(.ARM.attributes)
50	    *(.note*)
51	    *(.eh_frame*)
52	  }
53	
54	  ASSERT(_etext <= ORIGIN(flash) + LENGTH(flash),
55	         "boot stub exceeds the 128 KiB internal flash")
56	  ASSERT(_ebss + 32768 <= _estack,
57	         "boot stub leaves less than 32 KiB of stack")
58	}
