43	    [int64]$offset = [Convert]::ToInt32($line.Substring(3, 4), 16)
44	    $recordType = [Convert]::ToInt32($line.Substring(7, 2), 16)
45	
46	    switch ($recordType) {
47	      0 {
48	        [int64]$start = $baseAddress + $offset
49	        [int64]$end = $start + $byteCount
50	        if ($null -eq $minAddress -or $start -lt $minAddress) {
51	          $minAddress = $start
52	        }
53	        if ($end -gt $maxAddress) {
54	          $maxAddress = $end
55	        }
