57	      2 { $baseAddress = ([int64][Convert]::ToInt32($line.Substring(9, 4), 16)) -shl 4 }
58	      4 { $baseAddress = ([int64][Convert]::ToInt32($line.Substring(9, 4), 16)) -shl 16 }
