  if (version != NULL && version[0] != '\0')
    {
      off = appendf(out, n, off, ",\"version\":\"%s\"", version);
      if (off < 0)
        {
          return -1;
        }
    }

  off = appendf(out, n, off, "}");
  return (off < 0) ? -1 : 0;
}

