156	int vg_ota_bcb_decode(const uint8_t *buf, uint32_t len,
157	                      struct vg_ota_bcb *out)
158	{
159	  uint32_t stored_crc;
160	  uint32_t calc_crc;
161	
162	  if (buf == 0 || out == 0 || len != VG_OTA_BCB_FILE_BYTES)
163	    {
164	      return -EINVAL;
165	    }
166	
167	  if (rd32(&buf[OFF_MAGIC]) != VG_OTA_BCB_MAGIC ||
168	      rd16(&buf[OFF_FORMAT]) != VG_OTA_BCB_FORMAT ||
169	      rd16(&buf[OFF_HEADER_SIZE]) != VG_OTA_BCB_HEADER_BYTES)
170	    {
171	      return -EINVAL;
172	    }
173	
174	  stored_crc = rd32(&buf[OFF_CRC32]);
175	  calc_crc = vg_ota_crc32(buf, OFF_CRC32);
176	  if (stored_crc != calc_crc)
177	    {
178	      return -EBADMSG;
179	    }
180	
181	  zero_bytes((uint8_t *)out, sizeof(*out));
182	  out->seq = rd32(&buf[OFF_SEQ]);
183	  out->state = rd32(&buf[OFF_STATE]);
184	  out->slot = rd32(&buf[OFF_SLOT]);
185	  out->image_size = rd32(&buf[OFF_IMAGE_SIZE]);
186	  out->trial_count = rd32(&buf[OFF_TRIAL_COUNT]);
187	  out->flags = rd32(&buf[OFF_FLAGS]);
188	  copy_bytes((uint8_t *)out->version, &buf[OFF_VERSION],
189	             VG_OTA_BCB_VERSION_BYTES);
190	  out->version[VG_OTA_BCB_VERSION_BYTES] = '\0';
191	  copy_bytes((uint8_t *)out->task_id, &buf[OFF_TASK_ID],
192	             VG_OTA_BCB_TASK_ID_BYTES);
193	  out->task_id[VG_OTA_BCB_TASK_ID_BYTES] = '\0';
194	  copy_bytes(out->sha256, &buf[OFF_SHA256], VG_OTA_BCB_SHA256_BYTES);
195	  return fields_valid(out);
196	}
