10	static void w32(uint8_t *p, uint32_t v)
11	{
12	  p[0]=(uint8_t)v; p[1]=(uint8_t)(v>>8);
13	  p[2]=(uint8_t)(v>>16); p[3]=(uint8_t)(v>>24);
