25	static int valid(const struct vg_ota_manifest *m)
26	{
27	  return m->slot==VG_OTA_BCB_SLOT_B && m->image_size>=8 &&
28	    m->image_size<=VG_OTA_IMAGE_MAX_BYTES &&
29	    text_ok(m->version,32) && text_ok(m->task_id,40) &&
30	    text_ok(m->device_id,32) && text_ok(m->model,32) &&
31	    text_ok(m->key_id,16) && m->expires_at>m->issued_at &&
32	    (m->flags & ~VG_OTA_MANIFEST_FIXTURE)==0;
33	}
34	int vg_ota_manifest_decode(const uint8_t *p, uint32_t size,
35	                            struct vg_ota_manifest *m)
36	{
37	  uint32_t i;
38	  if (!p || !m || size!=512 || r32(p)!=0x464d4756u ||
39	      p[4]!=1 || p[5]!=0 || p[6]!=0 || p[7]!=2) return -EINVAL;
40	  if (vg_ota_crc32(p,508)!=r32(p+508)) return -EBADMSG;
41	  for (i=284; i<508; i++) if (p[i]) return -EINVAL;
42	  memset(m,0,sizeof(*m));
43	  m->slot=r32(p+8); m->image_size=r32(p+12);
44	  memcpy(m->version,p+16,32); memcpy(m->task_id,p+48,40);
45	  memcpy(m->sha256,p+88,32); memcpy(m->device_id,p+120,32);
46	  memcpy(m->model,p+152,32);
47	  m->issued_at=(uint64_t)r32(p+184)|((uint64_t)r32(p+188)<<32);
48	  m->expires_at=(uint64_t)r32(p+192)|((uint64_t)r32(p+196)<<32);
49	  memcpy(m->key_id,p+200,16); memcpy(m->signature,p+220,64);
50	  m->flags=r32(p+216);
51	  return valid(m) ? 0 : -EINVAL;
52	}
53	int vg_ota_manifest_encode(const struct vg_ota_manifest *m, uint8_t p[512])
54	{
55	  if (!m || !p || !valid(m)) return -EINVAL;
56	  memset(p,0,512);
57	  w32(p,0x464d4756u); p[4]=1; p[7]=2;
58	  w32(p+8,m->slot); w32(p+12,m->image_size);
59	  memcpy(p+16,m->version,32); memcpy(p+48,m->task_id,40);
60	  memcpy(p+88,m->sha256,32); memcpy(p+120,m->device_id,32);
61	  memcpy(p+152,m->model,32);
62	  w32(p+184,(uint32_t)m->issued_at); w32(p+188,(uint32_t)(m->issued_at>>32));
63	  w32(p+192,(uint32_t)m->expires_at); w32(p+196,(uint32_t)(m->expires_at>>32));
64	  memcpy(p+200,m->key_id,16); w32(p+216,m->flags);
65	  memcpy(p+220,m->signature,64); w32(p+508,vg_ota_crc32(p,508));
66	  return 0;
67	}
