  snprintf(path_tmp, sizeof(path_tmp), "%s/%s", g_temp_dir, VG_OTA_IMAGE_TMP_NAME);
  snprintf(path_bin, sizeof(path_bin), "%s/%s", g_temp_dir, VG_OTA_IMAGE_BIN_NAME);
